-- Generated from the JPA entities (MySQL 8, InnoDB). Fresh installs only; see db\manual for existing databases.
create table announcements (pinned bit not null, created_at datetime(6) not null, publish_at datetime(6), updated_at datetime(6) not null, id binary(16) not null, title varchar(200) not null, content TEXT not null, state enum ('ARCHIVED','DRAFT','PUBLISHED') not null, primary key (id)) engine=InnoDB;
create table app_settings (created_at datetime(6) not null, updated_at datetime(6) not null, id binary(16) not null, setting_key varchar(150) not null, description varchar(500), setting_value TEXT not null, primary key (id)) engine=InnoDB;
create table audit_logs (created_at datetime(6) not null, actor_id binary(16) not null, id binary(16) not null, target_type varchar(40) not null, action varchar(60) not null, target_id varchar(64), actor_email varchar(254) not null, details TEXT, primary key (id)) engine=InnoDB;
create table guidelines (active bit not null, sequence_order integer not null, created_at datetime(6) not null, updated_at datetime(6) not null, id binary(16) not null, title varchar(200) not null, file_key varchar(300), content TEXT not null, file_name varchar(255), primary key (id)) engine=InnoDB;
create table idea_attachments (created_at datetime(6) not null, size_bytes bigint not null, id binary(16) not null, idea_id binary(16) not null, uploaded_by binary(16) not null, content_type varchar(150) not null, object_key varchar(300) not null, file_name varchar(255) not null, primary key (id)) engine=InnoDB;
create table idea_likes (created_at datetime(6) not null, id binary(16) not null, idea_id binary(16) not null, user_id binary(16) not null, primary key (id)) engine=InnoDB;
create table idea_stage_history (changed_at datetime(6) not null, changed_by_id binary(16) not null, id binary(16) not null, idea_id binary(16) not null, reason TEXT not null, decision enum ('APPROVE','ARCHIVE','PROMOTE','REJECT','REQUEST_CHANGES','RESTORE') not null, from_stage enum ('DEMO','IDEA_SUBMISSION','PRESENTATION','SCREENING'), from_status enum ('APPROVED','ARCHIVED','CHANGES_REQUESTED','DRAFT','REJECTED','SUBMITTED','UNDER_REVIEW'), to_stage enum ('DEMO','IDEA_SUBMISSION','PRESENTATION','SCREENING') not null, to_status enum ('APPROVED','ARCHIVED','CHANGES_REQUESTED','DRAFT','REJECTED','SUBMITTED','UNDER_REVIEW') not null, primary key (id)) engine=InnoDB;
create table idea_tags (idea_id binary(16) not null, tag varchar(30) not null, primary key (idea_id, tag)) engine=InnoDB;
create table idea_team_members (created_at datetime(6) not null, updated_at datetime(6) not null, id binary(16) not null, idea_id binary(16) not null, role_in_team varchar(100) not null, department varchar(150), name varchar(150) not null, email varchar(254) not null, primary key (id)) engine=InnoDB;
create table ideas (created_at datetime(6) not null, like_count bigint not null, updated_at datetime(6) not null, id binary(16) not null, owner_id binary(16) not null, title varchar(200) not null, target_customer varchar(500), summary varchar(1000) not null, poster_url varchar(2048), admin_notes TEXT, business_impact TEXT, description TEXT not null, category enum ('AI_DATA_ANALYTICS','AR_VR','CUSTOMER_BUSINESS_SOLUTIONS','DIGITAL_MANUFACTURING','DIGITAL_TWINS','ENERGY_SUSTAINABILITY','INDUSTRIAL_AUTOMATION','MODELLING_SIMULATION','PRODUCT_PROCESS_INNOVATION','QUALITY_RELIABILITY','ROBOTICS','SAFETY_ERGONOMICS') not null, stage enum ('DEMO','IDEA_SUBMISSION','PRESENTATION','SCREENING') not null, status enum ('APPROVED','ARCHIVED','CHANGES_REQUESTED','DRAFT','REJECTED','SUBMITTED','UNDER_REVIEW') not null, primary key (id)) engine=InnoDB;
create table notifications (is_read bit not null, created_at datetime(6) not null, id binary(16) not null, recipient_id binary(16) not null, type varchar(80) not null, message TEXT not null, primary key (id)) engine=InnoDB;
create table stage_configs (enabled bit not null, end_date date, sequence_order integer not null, start_date date, created_at datetime(6) not null, updated_at datetime(6) not null, id binary(16) not null, updated_by binary(16), display_name varchar(100) not null, stage enum ('DEMO','IDEA_SUBMISSION','PRESENTATION','SCREENING') not null, primary key (id)) engine=InnoDB;
create table users (created_at datetime(6) not null, updated_at datetime(6) not null, id binary(16) not null, company varchar(150), department varchar(150), designation varchar(150), name varchar(150) not null, email varchar(254) not null, password_hash varchar(255) not null, role enum ('ADMIN','EMPLOYEE','ORGANIZER','REVIEWER') not null, primary key (id)) engine=InnoDB;
create table whatsapp_delivery_attempts (delivered_count integer not null, recipient_count integer not null, attempted_at datetime(6) not null, announcement_id binary(16) not null, attempted_by binary(16) not null, id binary(16) not null, error varchar(1000), provider_message_id varchar(1000), status enum ('FAILED','NOT_CONFIGURED','PARTIAL','SENT') not null, primary key (id)) engine=InnoDB;
